package ru.neverland.runtime;
import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import org.bukkit.*;import org.bukkit.block.Block;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.event.inventory.InventoryType;
import ru.neverland.core.*;import ru.neverland.townysieges.*;import ru.neverland.townybuilds.construction.*;

/** Explicit account/readiness and combat fixtures; real registered geometry, inventory, bank observers and world. */
public final class RepairRuntimeProbe extends CampLootRuntimeProbe {
    boolean repairExtended;Player mayor;Inventory mayorTop;InventoryView mayorView;RaidRepairs.Quote half;double wallet;UUID repair;
    @Override void finish()throws Exception{
        if(!extended||repairExtended){super.finish();return;}repairExtended=true;
        if(!restart){await(plugin.repairs().quote(DEF,"town_hall"),q->{checkNative(q);});return;}
        UUID checkpoint=UUID.fromString(Files.readString(proof.resolve("repair-checkpoint.txt")));await(plugin.repairs().store().get(checkpoint),job->{try{
            check(job.state().equals("REVIEW_BANK"),"repair bank intent survives native restart as review without a second debit");await(plugin.repairs().store().resolve(checkpoint,"retry","native admin","fixture confirms bank was never called"),ignored->{try{prepareHalf();}catch(Exception e){throw new CompletionException(e);}});
        }catch(Exception e){throw new CompletionException(e);}});
    }
    void checkNative(RaidRepairs.Quote q){try{
        check(q.lost()>0&&q.cells().stream().anyMatch(c->c.block().material().equals("LECTERN")&&c.missing()),"real TNT destruction retained for aggregate building repair");
        await(plugin.repairs().store().create(MAYOR,q.plan(),q.maximum(),q.lost(),q.cents(),90000,q.cells()),job->{try{Files.writeString(proof.resolve("repair-checkpoint.txt"),job.id().toString());check(job.state().equals("PAYING"),"repair intent is durable before external economy call");await(plugin.repairs().store().get(job.id()),confirmed->{try{check(confirmed!=null,"repair intent can be read before shutdown");CompletableFuture.supplyAsync(()->{try(var db=java.sql.DriverManager.getConnection("jdbc:sqlite:"+plugin.getDataFolder().toPath().resolve("raids.db").toAbsolutePath());var query=db.prepareStatement("SELECT state FROM building_repairs WHERE id=?")){query.setString(1,confirmed.id().toString());try(var row=query.executeQuery()){return row.next()?row.getString(1):"MISSING";}}catch(Exception e){throw new CompletionException(e);}}).whenComplete((state,error)->{if(error!=null){fail(error);return;}later(1,()->{Files.writeString(proof.resolve("confirmed-repair.txt"),state);check(state.equals("PAYING"),"independent SQLite connection confirms committed bank intent");finish();});});}catch(Exception e){throw new CompletionException(e);}});}catch(Exception e){throw new CompletionException(e);}});
    }catch(Exception e){throw new CompletionException(e);}}
    void makeMayor(){mayorTop=Bukkit.createInventory(null,9);
        mayor=(Player)Proxy.newProxyInstance(Player.class.getClassLoader(),new Class<?>[]{Player.class},(p,m,a)->switch(m.getName()){
            case "getUniqueId"->MAYOR;case "getName"->"TntMayor";case "getWorld"->world;case "getServer"->Bukkit.getServer();case "getLocation"->origin.clone();case "getScheduler"->actor.player.getScheduler();case "isOnline","isOp","hasPermission"->true;case "isDead"->false;case "getGameMode"->GameMode.SURVIVAL;case "getOpenInventory"->mayorView;case "openInventory"->{mayorTop=(Inventory)a[0];yield mayorView;}case "closeInventory"->{mayorTop=Bukkit.createInventory(null,9);yield null;}case "sendMessage"->null;case "hashCode"->MAYOR.hashCode();case "equals"->p==a[0];default->null;});
        mayorView=(InventoryView)Proxy.newProxyInstance(InventoryView.class.getClassLoader(),new Class<?>[]{InventoryView.class},(p,m,a)->switch(m.getName()){case "getTopInventory"->mayorTop;case "getBottomInventory"->actor.bottom;case "getPlayer"->mayor;case "getType"->InventoryType.CHEST;default->null;});
    }
    void prepareHalf()throws Exception{
        makeMayor();set(plugin.repairs(),"bank",new RepairBank(){@Override public boolean ready(UUID d,UUID a){return true;}});var plan=new RepairPlans().plan(DEF,"town_hall");
        var worldWork=new ArrayList<CompletableFuture<Void>>();var groups=new LinkedHashMap<String,List<RepairPlans.Cell>>();for(var c:plan.cells())groups.computeIfAbsent((c.key().x()>>4)+":"+(c.key().z()>>4),k->new ArrayList<>()).add(c);
        for(var group:groups.values()){var f=new CompletableFuture<Void>();worldWork.add(f);var at=group.get(0).key();SuiteScheduler.region(plugin,new Location(world,at.x(),at.y(),at.z()),()->{try{for(var c:group){var b=world.getBlockAt(c.key().x(),c.key().y(),c.key().z());b.setBlockData(Bukkit.createBlockData(c.data()),false);if(!c.top().isEmpty())b.getRelative(0,1,0).setBlockData(Bukkit.createBlockData(c.top()),false);}f.complete(null);}catch(Throwable e){f.completeExceptionally(e);}});}
        await(CompletableFuture.allOf(worldWork.toArray(CompletableFuture[]::new)),v->await(new BuildingDamageStore(store).list(DEF,"town_hall"),rows->{var resets=rows.stream().map(d->store.reset(d.key()).toCompletableFuture()).toArray(CompletableFuture[]::new);await(CompletableFuture.allOf(resets),ignored->{try{var hits=plan.cells().stream().map(c->new RaidStore.Hit(c.key(),DEF,c.material(),1,plugin.raids().settings().hp(c.material()),plugin.raids().settings().hp(c.material())/2,"town_hall")).toList();check(hits.size()<6000,"native registered building fits bounded damage batch");await(store.damage(UUID.randomUUID(),ACTOR.toString(),ATT,DEF,System.currentTimeMillis(),1800,hits),applied->awaitQuoteHalf());}catch(Exception e){throw new CompletionException(e);}});}));
    }
    void awaitQuoteHalf(){try{await(plugin.repairs().quote(DEF,"town_hall"),q->{try{
        half=q;check(Math.abs(q.lost()/q.maximum()-.5)<.0000001&&q.cents()==q.plan().price()/2,"50 percent aggregate HP costs exactly 50 percent of current level");
        double current=defender.getAccount().getHoldingBalance();defender.getAccount().withdraw(current,"native insufficient funds seed");boolean denied=false;try{plugin.repairs().start(mayor,q);}catch(IllegalArgumentException expected){denied=expected.getMessage().contains("недостаточно");}check(denied&&defender.getAccount().getHoldingBalance()==0,"insufficient town treasury rejects repair before payment and world changes");
        defender.getAccount().deposit(q.cents()/100.0+100,"native funded repair seed");wallet=defender.getAccount().getHoldingBalance();plugin.repairs().open(mayor,"town_hall");later(12,()->{check(mayorTop.getItem(11)!=null&&mayorTop.getItem(11).getType()==Material.ANVIL&&mayorTop.getItem(15).getType()==Material.LIME_CONCRETE,"repair menu shows shared integrity, exact cost and affordable confirmation");plugin.repairs().start(mayor,q);later(100,()->paidChecks());});
    }catch(Exception e){throw new CompletionException(e);}});}catch(Exception e){throw new CompletionException(e);}}
    void paidChecks(){await(plugin.repairs().store().list(false),jobs->{try{
        var job=jobs.stream().filter(j->j.state().equals("DONE")).findFirst().orElseThrow();repair=job.id();check(Math.abs(defender.getAccount().getHoldingBalance()-(wallet-half.cents()/100.0))<.00001,"production repair debits only town balance through real Towny observer");
        await(plugin.repairs().quote(DEF,"town_hall"),q->{try{check(q.lost()==0&&q.cents()==0,"paid repair restores aggregate HP completely");plugin.repairs().pulse();later(10,()->{check(Math.abs(defender.getAccount().getHoldingBalance()-(wallet-half.cents()/100.0))<.00001,"repair completion cannot debit the town twice");destroyedRepair();});}catch(Exception e){throw new CompletionException(e);}});
    }catch(Exception e){throw new CompletionException(e);}});}
    void destroyedRepair()throws Exception{
        var c=half.plan().cells().stream().filter(cell->cell.top().isEmpty()&&!cell.material().equals("LECTERN")).findFirst().orElseThrow();origin=new Location(world,c.key().x()+.5,c.key().y()+.5,c.key().z()+.5);double max=plugin.raids().settings().hp(c.material());
        await(store.damage(UUID.randomUUID(),ACTOR.toString(),ATT,DEF,System.currentTimeMillis(),1800,List.of(new RaidStore.Hit(c.key(),DEF,c.material(),2,max,max,"town_hall"))),hits->{try{block(c.key().x(),c.key().y(),c.key().z()).setType(Material.AIR,false);await(store.finish(hits.get(0),true),v->{try{await(plugin.repairs().quote(DEF,"town_hall"),q->{try{check(q.cells().size()==1&&q.cells().get(0).missing(),"destroyed registered cell included in building repair quote");plugin.repairs().start(mayor,q);later(35,()->{check(block(c.key().x(),c.key().y(),c.key().z()).getType()==Material.valueOf(c.material()),"paid repair physically restores destroyed blueprint block");defenseChecks();});}catch(Exception e){throw new CompletionException(e);}});}catch(Exception e){throw new CompletionException(e);}});}catch(Exception e){throw new CompletionException(e);}});
    }
    void defenseChecks()throws Exception{
        data.town(DEF).setLevel("fortress_wall",5);data.town(DEF).setConstructionSite(new ConstructionSite("fortress_wall",world.getUID(),20,159,40,org.bukkit.block.BlockFace.NORTH,5,5,1,false));data.markDirty();
        var service=(SiegeService)field(plugin,"service");service.reload(service.settings());var protection=plugin.loot().protection(DEF);check(protection.levels()>=5&&protection.effective().moneyBps()<1000&&protection.effective().resourcesBps()<1000,"real operational city defense reduces money and resource shares");
        var permit=new RaidController.Permit(ACTOR,ATT,DEF,UUID.randomUUID(),System.currentTimeMillis(),false);await(plugin.loot().arm(permit,new RaidStore.Key(world.getUID(),31,160,8),new byte[0]),row->{try{
            check(row.moneyBps()==protection.effective().moneyBps()&&row.policy().contains("Защита:"),"effective protected percentages and calculation frozen in durable loot receipt");await(plugin.loot().store().change(row.id(),"ARMED","VOID","native policy quote only"),v->{try{
                var records=new ArrayList<AuditRecord>();AuditJournal.scan(plugin.getDataFolder().toPath().resolve("audit"),records::add);check(records.stream().anyMatch(r->r.kind().equals("BUILDING_REPAIR")&&r.outcome().equals("DONE")&&r.money().equals(AuditTrail.cents(half.cents()))),"admin journal contains repair price, building integrity and successful completion");
                var menu=field(Bukkit.getPluginManager().getPlugin("NeverLandTownyControl"),"adminMenu");call(menu,"raids",new Class<?>[]{Player.class},actor.player);check(actor.top.getItem(20).getType()==Material.ANVIL&&actor.top.getItem(4).getType()==Material.SHIELD,"admin raid panel separates repairs and defense loot calculations");finish();
            }catch(Exception e){throw new CompletionException(e);}});
        }catch(Exception e){throw new CompletionException(e);}});
    }
}
